edits.newText:
/**
 * A point that no extent of a given set covers — the honest “nothing here” for
 * the point-filter empty state. Derived from the seed instead of hard-coded: the
 * overview maps cover large parts of Europe (Berlin was “outside” for a while),
 * and since 7-21 four records state a whole-globe extent
 * (`W 180°-E 180°/N 90°-S 90°`), so **no** point is outside the whole corpus any
 * more. The empty state is therefore provoked inside a scope the check can filter
 * to: every swisstopo edition documents the same Swiss box, so a Pacific point is
 * outside all of them and the app is asked `?p=swisstopo&at=…`.
 */
const pointOutside = (boxes) => {
  const usable = boxes.filter(Boolean);
  if (usable.length === 0) return { lat: 52.52, lon: 13.405 };
  for (let lat = 62; lat >= -54; lat -= 4) {
    for (let lon = -178; lon <= 178; lon += 4) {
      const covered = usable.some((b) => lon >= b.west && lon <= b.east && lat >= b.south && lat <= b.north);
      if (!covered) return { lat, lon };
    }
  }
  return { lat: -58, lon: -178 };
};
const asLatLon = (point) => `${point.lat.toFixed(4)}%2C${point.lon.toFixed(4)}`;

/** The regional scope for the empty state: the swisstopo editions’ Swiss boxes. */
const regionalPoint = pointOutside(
  [...recordIndex.values()].filter((record) => record.providerId === 'swisstopo').map((record) => record.extent),
);
const regionalAt = asLatLon(regionalPoint);

/**
 * The mirror case, from the same data: a whole-globe sheet is *right* to answer a
 * South-Pacific point, so the point filter must not claim “no maps here” there —
 * it returns the globe sheets and offers its own removal like any other filter.
 * Only asserted while such a sheet is in the seed (its extent is a full 360°).
 */
const globeRecord = [...recordIndex.values()].find((record) => record.extent && record.extent.east - record.extent.west > 350);
const worldPointAt = asLatLon({ lat: -58, lon: -178 });

