// The empty state is provoked inside the swisstopo scope: a whole-globe sheet
// covers every point of the corpus, so “no record covers this point” can only
// be asked of a filtered scope (see pointOutside above).
await cdp.send('Page.navigate', { url: `${BASE_URL}/?from=1781&to=1900&p=swisstopo&at=${regionalAt}` });
let emptyPoint = null;
try {
  emptyPoint = await cdp.waitFor(
    `(() => {
      const chip = document.querySelector('#point-filter');
      if (!chip || chip.hidden) return '';
      const state = document.querySelector('#results-state');
      return { rows: document.querySelectorAll('#result-list > *').length, empty: state?.hidden === false, text: state?.textContent.slice(0, 90) || '' };
    })()`,
    { label: 'empty point state', timeout: 8_000 },
  );
} catch {
  /* reported below */
}
const pointRemove = await cdp.eval(`(() => {
  const button = [...document.querySelectorAll('#results-state button')].find((b) => /Punktfilter/.test(b.textContent));
  if (!button) return false;
  button.click();
  return true;
})()`);
await sleep(500);
const afterPointRemove = await cdp.eval(`({ rows: document.querySelectorAll('#result-list > *').length, at: new URLSearchParams(location.search).get('at') })`);
check(
  `a point outside every footprint of the filtered scope says so and can be removed on its own (${regionalPoint.lat}, ${regionalPoint.lon})`,
  Boolean(emptyPoint) && emptyPoint.rows === 0 && emptyPoint.empty && pointRemove === true && afterPointRemove.rows > 0 && !afterPointRemove.at,
  `${JSON.stringify(emptyPoint)} remove=${pointRemove} ${JSON.stringify(afterPointRemove)}`,
);

// The same point without the regional filter: the committed whole-globe sheets
// (their stated extent really is the world) answer it, and the point filter is
// removable from the chip row — the app must not pretend the world is empty.
if (globeRecord) {
  await cdp.send('Page.navigate', { url: `${BASE_URL}/?from=1781&to=1900&at=${worldPointAt}` });
  let globeAnswer = null;
  try {
    globeAnswer = await cdp.waitFor(
      `(() => {
        const list = document.querySelectorAll('#result-list > *');
        return list.length > 0 ? { rows: list.length, first: list[0].textContent.slice(0, 48), empty: document.querySelector('#results-state')?.hidden === false } : '';
      })()`,
      { label: 'globe answer', timeout: 8_000 },
    );
  } catch {
    /* reported below */
  }
  const globeRemove = await cdp.eval(`(() => {
    const chip = document.querySelector('#point-filter');
    const button = chip ? [...chip.querySelectorAll('button')].find((b) => /Punktfilter/.test(b.textContent)) : null;
    if (!button || chip.hidden) return false;
    button.click();
    return true;
  })()`);
  await sleep(600);
  const afterGlobeRemove = await cdp.eval(`({ rows: document.querySelectorAll('#result-list > *').length, at: new URLSearchParams(location.search).get('at') })`);
  check(
    `a South-Pacific point is answered by the whole-globe sheets (${globeRecord.id}) instead of an empty state`,
    Boolean(globeAnswer) && globeAnswer.rows > 0 && !globeAnswer.empty && globeRemove === true && afterGlobeRemove.rows > 0 && !afterGlobeRemove.at,
    `${JSON.stringify(globeAnswer)} remove=${globeRemove} ${JSON.stringify(afterGlobeRemove)}`,
  );
} else {
  check('a South-Pacific point is answered by the whole-globe sheets', true, 'skipped – no whole-globe sheet in the seed');
}

