const pinOne = await pinResult(0);
const pinTwo = await pinResult(1);
let pinnedIds = (pinTwo.cmp || pinOne.cmp).split(',').filter(Boolean);
check(
  'compare: two records can be pinned and the list is shareable',
  pinnedIds.length === 2 &&
    pinTwo.listItems === 2 &&
    pinTwo.toolbarHidden === false &&
    /gemerkt/.test(pinTwo.status) &&
    new URLSearchParams(await cdp.eval(`location.search`)).get('cmp') === pinnedIds.join(','),
  `${pinnedIds.join(' + ')} · status: ${pinTwo.status.slice(0, 60)}`,
);

/*
 * The coupling is only *testable* on a pair whose documented extents really
 * meet: the first two rows are the two oldest records, and since 7-21 that is a
 * whole-globe sheet (1546, extent −180…180 / −90…90) next to “Das Zürychgow”
 * (1547). Zooming the globe leaves a region that still contains the whole
 * Zürich sheet, so the coupled partner honestly keeps its whole sheet.
 * The pair for the coupling checks is therefore **computed from the seed**: the
 * two records that share the largest part of the smaller of their extents, so a
 * zoomed cut-out on one of them is also inside the other's documented extent.
 * The globe pair is asserted right below as its own honest case.
 */
const globeAndRegion = (() => {
  const candidates = [...recordIndex.values()].filter((record) => record.iiifManifest && record.extent);
  const area = (box) => (box.east - box.west) * (box.north - box.south);
  const globe = candidates.find((record) => record.extent.east - record.extent.west > 350);
  const region = candidates
    .filter((record) => record !== globe && Math.abs((record.extent.north + record.extent.south) / 2) > 40)
    .sort((a, b) => area(b.extent) - area(a.extent))[0];
  return globe && region ? [globe, region] : null;
})();
const couplingPair = (() => {
  const candidates = [...recordIndex.values()].filter((record) => record.iiifManifest && record.extent);
  const area = (box) => (box.east - box.west) * (box.north - box.south);
  let best = null;
  let bestShare = 0;
  for (let i = 0; i < candidates.length; i += 1) {
