edits.newText:
check(
  'a shared comparison link reopens that cut-out in its own pane and, coupled, in the other',
  Boolean(restoredOwn && restoredOther) &&
    restoredOwn.src.includes(`${cutout?.region}`) &&
    restoredUrl.includes(`${pinnedIds[0]}@${cutout?.region}`) &&
    restoredUrl.includes(`${pinnedIds[1]}@`),
  `pane 1 ${restoredOwn?.readout ?? 'no cut-out'} · pane 2 ${restoredOther?.readout ?? 'no cut-out'} · link cvv "${restoredUrl}"`,
);

/* --- 8c4. a coupled pane that the sheet does not cover says so -------- */
// The measured case behind the 7-21 red harness: a whole-globe sheet next to a
// regional sheet. Once the globe pane's cut-out leaves the regional extent there
// is nothing to show, so the pane keeps its whole sheet **and explains itself**
// (compare.js `coupledView` → `coverage: 'outside'`).
if (globeAndRegion) {
  const [globe, region] = globeAndRegion;
  await cdp.send('Page.navigate', { url: `${BASE_URL}/?cmp=${encodeURIComponent([globe.id, region.id].join(','))}` });
  await cdp.waitFor(`document.querySelectorAll('#result-list > *').length > 0`, { label: 'globe pair page' });
  await sleep(400);
  await cdp.click('#compare-open');
  await cdp.waitFor(`document.querySelector('#compare-view') && !document.querySelector('#compare-view').hidden`, { label: 'globe pair compare view', timeout: 10_000 });
  await cdp.waitFor(readyPanes, { label: 'globe pair panes ready', timeout: 60_000 }).catch(() => null);
  await cdp.eval(`document.querySelector('[data-compare-stage="0"]').focus(); true`);
  let outsideNote = null;
  for (let press = 0; press < 5 && !outsideNote; press += 1) {
    await cdp.pressKey('+', { keyCode: 187 });
    outsideNote = await cdp
      .waitFor(
        `(() => {
          const note = document.querySelector('[data-compare-coverage="1"]');
          const figure = note?.closest('figure');
          const state = document.querySelector('#compare-sync-hint')?.textContent || '';
          if (!note || note.hidden || figure?.dataset.coverage !== 'outside' || !/ausserhalb der belegten Ausdehnung/.test(state)) return '';
          const img = document.querySelectorAll('${comparePaneSelector}')[1];
          return { note: note.textContent, state, borderLeft: getComputedStyle(note).borderLeftWidth, pane2: (img?.src || '').split('/').slice(-3).join('/') };
        })()`,
        { label: 'honest out-of-coverage note', timeout: 8_000 },
      )
      .catch(() => null);
  }
  const paneSizes = await cdp.eval(`[...document.querySelectorAll('[data-compare-readout]')].map((node) => node.textContent)`);
  check(
    `a coupled pane whose sheet does not cover the cut-out says so instead of quietly staying wide (${globe.id} vs ${region.id})`,
    Boolean(outsideNote) && /belegt den gezeigten Ausschnitt nicht/.test(outsideNote?.note ?? '') && outsideNote?.borderLeft === '4px',
    `${JSON.stringify(outsideNote)} · readouts ${JSON.stringify(paneSizes)}`,
  );
  await cdp.screenshot(path.join(OUT_DIR, '11d-compare-outside.png')).then(() => report.screenshots.push('11d-compare-outside.png'));
} else {
  check('a coupled pane whose sheet does not cover the cut-out says so', true, 'skipped – no globe/regional pair in the seed');
}

