const couplingPair = (() => {
  // A whole-globe sheet overlaps every box completely, so it always “wins” a
  // plain share metric; the coupling is testable only on two *comparable*
  // extents, and both sides must mostly contain the other.
  const candidates = [...recordIndex.values()].filter(
    (record) => record.iiifManifest && record.extent && record.extent.east - record.extent.west < 350,
  );
  const area = (box) => (box.east - box.west) * (box.north - box.south);
  let best = null;
  let bestShare = 0;
  for (let i = 0; i < candidates.length; i += 1) {
    for (let j = i + 1; j < candidates.length; j += 1) {
      const a = candidates[i].extent;
      const b = candidates[j].extent;
      const sharedW = Math.min(a.east, b.east) - Math.max(a.west, b.west);
      const sharedH = Math.min(a.north, b.north) - Math.max(a.south, b.south);
      if (sharedW <= 0 || sharedH <= 0) continue;
      const shared = sharedW * sharedH;
      const share = Math.min(shared / area(a), shared / area(b));
      if (share > bestShare) {
        bestShare = share;
        best = [candidates[i], candidates[j]];
      }
    }
  }
  return best;
})();

