  `a point no ${uncoveredPoint.from}–${uncoveredPoint.to} sheet documents says so and can be removed on its own (${uncoveredPoint.lat}, ${uncoveredPoint.lon})`,
  Boolean(emptyPoint) && emptyPoint.rows === 0 && emptyPoint.empty && pointRemove === true && afterPointRemove.rows > 0 && !afterPointRemove.at,
  `${JSON.stringify(emptyPoint)} remove=${pointRemove} ${JSON.stringify(afterPointRemove)}`,
);

// The mirror case, from the same data: without a period filter the point *is*
// answered by the committed whole-globe sheets (their stated extent really is
// the world). The app must not reach “no maps here” by hiding global sheets,
// and the filter has to be removable from the chip row like any other.
const globeForProbe = [...recordIndex.values()].find((record) => record.extent && record.extent.east - record.extent.west > 350);
if (globeForProbe) {
  await cdp.send('Page.navigate', { url: `${BASE_URL}/?at=${uncoveredAt}` });
  let globeAnswer = null;
  try {
    globeAnswer = await cdp.waitFor(
      `(() => {
        const list = document.querySelectorAll('#result-list > *');
        if (list.length === 0) return '';
        const text = list[0].textContent;
        return text.includes(${JSON.stringify(globeForProbe.yearStart)}) ? { rows: list.length, first: text.slice(0, 56), empty: document.querySelector('#results-state')?.hidden === false } : '';
      })()`,
      { label: 'globe answer to the ocean point', timeout: 8_000 },
    );
  } catch {
    /* reported below */
  }
  const globeRemove = await cdp.eval(`(() => {
    const chip = document.querySelector('#point-filter');
    const button = chip && !chip.hidden ? [...chip.querySelectorAll('button')].find((b) => /Punktfilter/.test(b.textContent)) : null;
    if (!button) return false;
    button.click();
    return true;
  })()`);
  await sleep(600);
  const afterGlobeRemove = await cdp.eval(`({ rows: document.querySelectorAll('#result-list > *').length, at: new URLSearchParams(location.search).get('at') })`);
  check(
    `a South-Pacific point is answered by the whole-globe sheets (${globeForProbe.id}) instead of an empty state`,
    Boolean(globeAnswer) && globeAnswer.rows > 0 && !globeAnswer.empty && globeRemove === true && afterGlobeRemove.rows > 0 && !afterGlobeRemove.at,
    `${JSON.stringify(globeAnswer)} remove=${globeRemove} ${JSON.stringify(afterGlobeRemove)}`,
  );
} else {
  check('a South-Pacific point is answered by the whole-globe sheets', true, 'skipped – no whole-globe sheet in the seed');
}

