/* --- 8c4. a coupled pane whose sheet does not cover the cut-out ------- */
// The other half of the coupling promise (compare.js `coupledView` →
// `coverage: 'outside'`): a transferred cut-out that lies beside a sheet's
// documented extent must not be clamped onto the sheet (which would show the
// wrong place); the pane keeps its whole sheet and says why. The measured case
// is the whole-globe 1546 sheet next to a Zürich sheet, which is exactly the
// pair the 7-21 globe extents put in the first two result rows.
const scalePair = (() => {
  const candidates = [...recordIndex.values()].filter((record) => record.iiifManifest && record.extent);
  const span = (record) => Math.max(record.extent.east - record.extent.west, record.extent.north - record.extent.south);
  const globe = candidates.find((record) => record.extent.east - record.extent.west > 350);
  const regional = candidates
    .filter((record) => record !== globe && span(record) < 20)
    .sort((a, b) => span(b) - span(a))[0];
  return globe && regional ? [globe, regional] : null;
})();
if (scalePair) {
  const [globe, regional] = scalePair;
  await cdp.send('Page.navigate', { url: `${BASE_URL}/?cmp=${encodeURIComponent(`${globe.id},${regional.id}`)}` });
  await cdp.waitFor(`document.querySelectorAll('#result-list > *').length > 0`, { label: 'scale pair page' });
  await sleep(400);
  await cdp.click('#compare-open');
  await cdp.waitFor(`document.querySelector('#compare-view') && !document.querySelector('#compare-view').hidden`, { label: 'scale pair compare view', timeout: 10_000 });
  await cdp.waitFor(readyPanes, { label: 'scale pair panes ready', timeout: 60_000 }).catch(() => null);
  await cdp.eval(`document.querySelector('[data-compare-stage="0"]').focus(); true`);
  let outsideNote = null;
  for (let press = 0; press < 5 && !outsideNote; press += 1) {
    await cdp.pressKey('+', { keyCode: 187 });
    outsideNote = await cdp
      .waitFor(
        `(() => {
          const note = document.querySelector('[data-compare-coverage="1"]');
          const figure = note?.closest('figure');
          const state = document.querySelector('#compare-sync-hint')?.textContent || '';
          if (!note || note.hidden || figure?.dataset.coverage !== 'outside' || !/ausserhalb der belegten Ausdehnung/.test(state)) return '';
          const readouts = [...document.querySelectorAll('[data-compare-readout]')].map((node) => node.textContent);
          return { note: note.textContent, state, borderLeft: getComputedStyle(note).borderLeftWidth, readouts };
        })()`,
        { label: 'honest out-of-coverage note', timeout: 8_000 },
      )
      .catch(() => null);
  }
  check(
    `a coupled pane whose sheet does not cover the cut-out says so (${globe.id} vs ${regional.id})`,
    Boolean(outsideNote) &&
      /belegt den gezeigten Ausschnitt nicht/.test(outsideNote?.note ?? '') &&
      outsideNote?.borderLeft === '4px' &&
      /Gesamtansicht/.test(outsideNote?.readouts?.[1] ?? ''),
    `${JSON.stringify(outsideNote)}`,
  );
  await cdp.screenshot(path.join(OUT_DIR, '11d-compare-outside.png')).then(() => report.screenshots.push('11d-compare-outside.png'));
} else {
  check('a coupled pane whose sheet does not cover the cut-out says so', true, 'skipped – no globe/regional pair in the seed');
}

