/**
 * The pane that is not part of the current cut-out explains itself, so the
 * visitor does not have to guess why one map stayed wide while the other
 * zoomed (the same honesty the panel uses for a missing manifest). The sentence
 * depends on what the pane really shows: a pane that never left its whole sheet
 * says so, a pane that followed an earlier cut-out keeps that cut-out and says
 * that instead — a claim about the whole sheet would be wrong there (measured
 * with the 1546 globe sheet next to a Denmark sheet: the first zoom step still
 * reached Denmark as a whole, the second did not).
 */
function refreshPaneCoverage() {
  for (const pane of panes) {
    const note = viewBody?.querySelector(`[data-compare-coverage="${pane.index}"]`);
    const coverage = pane.failed ? '' : pane.coverage || '';
    note?.closest('figure')?.setAttribute('data-coverage', coverage);
    if (!note) continue;
    const shifted = Boolean(pane.viewer?.getViewParam?.());
    const text =
      coverage === 'outside'
        ? shifted
          ? 'Der übertragene Ausschnitt liegt ausserhalb dieses Blattes – die Karte bleibt beim zuletzt gezeigten Ausschnitt stehen.'
          : 'Der übertragene Ausschnitt liegt ausserhalb dieses Blattes – das Blatt bleibt als Ganzes stehen.'
        : coverage === 'partial'
          ? 'Gezeigt wird der gemeinsame Bereich; das Blatt reicht nicht weiter.'
          : '';
    note.textContent = text;
    note.hidden = text === '';
  }
}

